SELECT 'andros_extra', 'Andros — 13. oswiadczenie STAN ZDROWIA PRACOWNIKA', false, 'factory', '[]'::jsonb, '[2]'::jsonb, NULL, '{"en": "<div></div>\n<div>\n<p class=\"c17\"><span class=\"c5\"></span></p>\n</div>\n<p class=\"c10\" style=\"text-align: center;\"><strong><span class=\"c12\">OŚWIADCZENIE</span></strong></p>\n<p class=\"c2\"><span class=\"c15\">Oświadczam, że niezwłocznie poinformuję zakład pracy o zachorowaniu na chorobę zakaźną, lub nosicielstwie choroby zakaźnej, kt&oacute;ra może negatywnie wpłynąć na produkty wytwarzane w Andros-Polska</span><span class=\"c15 c16\">1).</span></p>\n<p class=\"c6\"><span class=\"c1\"></span></p>\n<table style=\"width: 100%; table-layout: fixed; border-collapse: collapse; border: 0; margin-top: 40px; page-break-inside: avoid;\">\n<tbody>\n<tr>\n<td style=\"width: 100%; padding: 10px; text-align: left; vertical-align: bottom;\">\n<div style=\"font-weight: bold; margin-bottom: 5px;\">Data: {%Data dzisiejsza%}<br />Imię i Nazwisko: <hra>{%Imię%}</hra>&nbsp; <hra>{%Nazwisko%}</hra>&nbsp;</div>\n</td>\n<td style=\"width: 100%; padding: 10px; text-align: center; vertical-align: bottom;\">\n<div style=\"width: 240px; margin: 0 auto; float: right;\">\n<div style=\"width: 210px; height: 70px; margin: 0 auto 5px auto; border: 1px dashed #ccc; background-color: #fafafa; display: flex; align-items: center; justify-content: center;\">{%Podpis odręczny pracownika%}</div>\n<div style=\"border-top: 1px solid #000; padding-top: 5px; font-size: 10px; font-weight: bold;\">(Podpis / Signature)</div>\n</div>\n</td>\n</tr>\n</tbody>\n</table>\n<table class=\"c13\">\n<tbody>\n<tr class=\"c11\">\n<td class=\"c4\" colspan=\"1\" rowspan=\"1\">\n<p class=\"c0\"><span class=\"c9\">1)</span><span class=\"c7\">&nbsp;Rozp. UE </span><span class=\"c3\">852/2004 </span><span class=\"c8\">ROZDZIAŁ VIII HIGIENA OSOBISTA pkt 2</span><span class=\"c14\">&nbsp;&bdquo;Żadna osoba cierpiąca na chorobę, lub będąca jej nosicielką, kt&oacute;ra może być przenoszona poprzez żywność, bądź też stwierdza się u niej np. zainfekowane rany, zakażenia sk&oacute;ry, owrzodzenia lub biegunkę nie może uzyskać pozwolenia na pracę z żywnością ani na wejście do obszaru, w kt&oacute;rym pracuje się z żywnością w jakimkolwiek charakterze, jeśli występuje jakiekolwiek prawdopodobieństwo bezpośredniego lub pośredniego zanieczyszczenia. Każda osoba tak dotknięta i zatrudniona w przedsiębiorstwie sektora spożywczego i kt&oacute;ra prawdopodobnie będzie miała kontakt z żywnością musi niezwłocznie zgłosić chorobę lub symptomy, a jeżeli to możliwe, r&oacute;wnież ich powody, przedsiębiorstwu sektora spożywczego&rdquo;</span></p>\n</td>\n</tr>\n</tbody>\n</table>\n<p class=\"c6\"><div style=\"page-break-after: always\"></div><br /><br /><br /><br /></p>\n<p class=\"c10\" style=\"text-align: center;\"><strong><span class=\"c12\">ACKNOWLEDGEMENT</span></strong></p>\n<p class=\"c2\"><span class=\"c15\">I hereby confirm that I will immediately inform the employer about any infectious disease or carrier status of an infectious disease that may negatively affect the products manufactured at Andros-Polska</span><span class=\"c15 c16\">1).</span></p>\n<p class=\"c6\"><span class=\"c1\"></span></p>\n<table style=\"width: 100%; table-layout: fixed; border-collapse: collapse; border: 0; margin-top: 40px; page-break-inside: avoid;\">\n<tbody>\n<tr>\n<td style=\"width: 100%; padding: 10px; text-align: left; vertical-align: bottom;\">\n<div style=\"font-weight: bold; margin-bottom: 5px;\">Data: {%Data dzisiejsza%}<br />Imię i Nazwisko: <hra>{%Imię%}</hra>&nbsp; <hra>{%Nazwisko%}</hra>&nbsp;</div>\n</td>\n<td style=\"width: 100%; padding: 10px; text-align: center; vertical-align: bottom;\">\n<div style=\"width: 240px; margin: 0 auto; float: right;\">\n<div style=\"width: 210px; height: 70px; margin: 0 auto 5px auto; border: 1px dashed #ccc; background-color: #fafafa; display: flex; align-items: center; justify-content: center;\">{%Podpis odręczny pracownika%}</div>\n<div style=\"border-top: 1px solid #000; padding-top: 5px; font-size: 10px; font-weight: bold;\">(Podpis / Signature)</div>\n</div>\n</td>\n</tr>\n</tbody>\n</table>\n<table class=\"c13\">\n<tbody>\n<tr class=\"c11\">\n<td class=\"c4\" colspan=\"1\" rowspan=\"1\">\n<p class=\"c0\"><span class=\"c9\">1)</span><span class=\"c7\">&nbsp;EU Regulation 852/2004 CHAPTER VIII PERSONAL HYGIENE point 2: </span><span class=\"c14\">&bdquo;No person suffering from, or being a carrier of, a disease likely to be transmitted through food, or afflicted, for example, with infected wounds, skin infections, sores or diarrhea, shall be permitted to handle food or enter any food-handling area in any capacity if there is any likelihood of direct or indirect contamination. Any such person employed in a food business and who is likely to come into contact with food must immediately report the illness or symptoms, and if possible their causes, to the food business operator&rdquo;</span></p>\n</td>\n</tr>\n</tbody>\n</table>\n<p class=\"c6\"><span class=\"c1\"></span></p>", "es": "<div></div>\n<div>\n<p class=\"c17\"><span class=\"c5\"></span></p>\n</div>\n<p class=\"c10\" style=\"text-align: center;\"><strong><span class=\"c12\">OŚWIADCZENIE</span></strong></p>\n<p class=\"c2\"><span class=\"c15\">Oświadczam, że niezwłocznie poinformuję zakład pracy o zachorowaniu na chorobę zakaźną, lub nosicielstwie choroby zakaźnej, kt&oacute;ra może negatywnie wpłynąć na produkty wytwarzane w Andros-Polska</span><span class=\"c15 c16\">1).</span></p>\n<p class=\"c6\"><span class=\"c1\"></span></p>\n<table style=\"width: 100%; table-layout: fixed; border-collapse: collapse; border: 0; margin-top: 40px; page-break-inside: avoid;\">\n<tbody>\n<tr>\n<td style=\"width: 100%; padding: 10px; text-align: left; vertical-align: bottom;\">\n<div style=\"font-weight: bold; margin-bottom: 5px;\">Data: {%Data dzisiejsza%}<br />Imię i Nazwisko: <hra>{%Imię%}</hra>&nbsp; <hra>{%Nazwisko%}</hra>&nbsp;</div>\n</td>\